const r = $json.output;
const categorias = ['compatibilidad', 'envio', 'retiro', 'pago', 'precio', 'stock', 'garantia', 'devolucion', 'reclamo', 'pedido', 'otro'];

// Normaliza texto: minúsculas, sin tildes y sin espacios extra ("Sí " → "si", "Envío" → "envio")
const norm = v => String(v ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

// Si el parser fallo (vino por la salida de error) o no hay respuesta: se deriva a Juan
if (!r || typeof r !== 'object' || typeof r.respuesta !== 'string' || !r.respuesta.trim()) {
  return { json: { respuesta: '', derivar: 'si', categoria: 'otro', motivo: 'La IA no devolvio un formato valido', crudo: JSON.stringify($json).slice(0, 500) } };
}

let categoria = norm(r.categoria);
let derivar = norm(r.derivar || 'si').startsWith('n') ? 'no' : 'si';
let motivo = r.motivo || '';
let respuesta = r.respuesta.trim();

// Control extra por si acaso (el schema ya lo valida)
if (!categorias.includes(categoria)) {
  derivar = 'si';
  motivo = 'Categoria invalida: "' + categoria + '"';
}

// Los reclamos siempre los ve Juan
if (categoria === 'reclamo') derivar = 'si';

// En pedidos, la entrega se dice siempre igual
if (categoria === 'pedido') {
  respuesta = respuesta.replace(/ya (te )?(llego|llegó)/i, 'ya fue entregado');
}

// Sacar el "Cualquier cosa avisame" si termina con pregunta o es reclamo
const cierre = /\s*Cualquier cosa avisame\.?\s*$/i;
const sinSaludo = respuesta.replace(/^.*?como estas\?\s*/i, '').replace(cierre, '');
const lePregunta = /\?|\bcontame\b|\bdecime\b|\bpasame\b/i.test(sinSaludo);
if (lePregunta || categoria === 'reclamo') respuesta = respuesta.replace(cierre, '').trim();

// Sin signos de apertura (estilo WhatsApp)
respuesta = respuesta.replace(/[¿¡]/g, '');

// Si no se deriva, el motivo queda vacio
if (derivar === 'no') motivo = '';

return { json: { respuesta, derivar, categoria, motivo } };

// ============================================================
// Comparar canales - Scatto (opcion B)
// Compara TiendaNube (transferencia y tarjeta) contra Mercado Libre.
//
// Canales posibles por producto:
//   tiendanube   -> solo la tienda (ML no le conviene a nadie)
//   ambos        -> transferencia en la tienda es lo mas barato,
//                   pero con tarjeta conviene ML: se ofrecen los dos
//   mercadolibre -> ML es lo mas barato para todos
//   sin_stock    -> no hay stock en ningun lado
//
// Precio en la tienda: si el producto tiene precio promocional se usa
// ese; si no, el de lista. El descuento por transferencia se aplica
// siempre (se acumula con la promo).
// Si ML falla o no tiene stock, se usa solo TiendaNube.
// ============================================================

const base = $input.first().json;

// ---- Datos que podes cambiar vos ----
const DESCUENTO_TRANSFERENCIA = 0.05;   // 5% por transferencia (se suma al precio promocional)
const CUOTAS_TN = 'hasta 3 cuotas sin interes';  // '' para no mencionarlas
const CUOTAS_ML = 'en 6 cuotas';        // cambialo si cambias la promo de cuotas en ML ('' para no mencionarlas)
// -------------------------------------

// Formato argentino sin decimales: 31500 -> "31.500"
function fmt(n) {
  return Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

// Lee precio y stock crudos de TiendaNube
function leerTN(nodo) {
  try {
    const v = $(nodo).first().json.variants[0];
    const precioLista = Number(v.price);
    const promo = Number(v.promotional_price) || 0;
    const lista = (promo > 0 && promo < precioLista) ? promo : precioLista;
    if (!lista) return null;
    // En TiendaNube, stock null significa stock infinito
    const stock = (v.stock === null || v.stock === undefined) ? 999 : Number(v.stock);
    return {
      lista: lista,
      transferencia: Math.round(lista * (1 - DESCUENTO_TRANSFERENCIA)),
      stock: stock
    };
  } catch (e) {
    return null;
  }
}

// Texto de la condicion de pago en la tienda
function condicionTN(tn) {
  return 'pagando por transferencia en la tienda. Con tarjeta, MODO o Mercado Pago sale $' + fmt(tn.lista) +
    (CUOTAS_TN ? ' (' + CUOTAS_TN + ')' : '');
}

// Lee precio, stock, link y envio gratis de Mercado Libre
function leerML(nodo) {
  try {
    const j = $(nodo).first().json;
    const precio = Number(j.price);
    if (!precio) return null;                            // fallo la API o vino vacio
    if (j.status !== 'active') return null;              // publicacion pausada o cerrada
    if (Number(j.available_quantity) <= 0) return null;  // sin stock en ML
    const envioGratis = !!(j.shipping && j.shipping.free_shipping);
    return { precio: precio, link: j.permalink, envioGratis: envioGratis };
  } catch (e) {
    return null;
  }
}

// Arma el texto de beneficios de ML, por ejemplo "en 6 cuotas y con envio gratis"
function beneficiosML(ml) {
  const partes = [];
  if (CUOTAS_ML) partes.push(CUOTAS_ML);
  if (ml.envioGratis) partes.push('con envio gratis');
  return partes.join(' y ');
}

// Decide el canal para un producto
function decidir(tn, ml, linkTN) {
  const tnDisponible = tn && tn.stock > 0;

  // Estructura vacia por defecto
  const r = {
    canal: 'sin_stock',
    precio_final: '',
    condicion: 'sin stock por ahora',
    link_recomendado: '',
    tn_tarjeta: tn ? fmt(tn.lista) : '',
    ml_precio: '',
    ml_beneficios: '',
    ml_link: ''
  };

  // Caso 1: hay TiendaNube y hay ML
  if (tnDisponible && ml) {
    if (ml.precio < tn.transferencia) {
      // ML es lo mas barato para cualquiera
      r.canal = 'mercadolibre';
      r.precio_final = fmt(ml.precio);
      r.condicion = 'comprando por Mercado Libre';
      r.link_recomendado = ml.link;
      r.ml_precio = fmt(ml.precio);
      r.ml_beneficios = beneficiosML(ml);
      r.ml_link = ml.link;
      return r;
    }
    if (ml.precio < tn.lista) {
      // Transferencia en la tienda gana, pero con tarjeta conviene ML
      r.canal = 'ambos';
      r.precio_final = fmt(tn.transferencia);
      r.condicion = 'pagando por transferencia en la tienda';
      r.link_recomendado = linkTN;
      r.ml_precio = fmt(ml.precio);
      r.ml_beneficios = beneficiosML(ml);
      r.ml_link = ml.link;
      return r;
    }
    // ML igual o mas caro que la tienda con tarjeta: no suma nada ofrecerlo
    r.canal = 'tiendanube';
    r.precio_final = fmt(tn.transferencia);
    r.condicion = condicionTN(tn);
    r.link_recomendado = linkTN;
    return r;
  }

  // Caso 2: solo TiendaNube (ML fallo o sin stock)
  if (tnDisponible) {
    r.canal = 'tiendanube';
    r.precio_final = fmt(tn.transferencia);
    r.condicion = condicionTN(tn);
    r.link_recomendado = linkTN;
    return r;
  }

  // Caso 3: solo ML (TiendaNube sin stock)
  if (ml) {
    r.canal = 'mercadolibre';
    r.precio_final = fmt(ml.precio);
    r.condicion = 'comprando por Mercado Libre';
    r.link_recomendado = ml.link;
    r.ml_precio = fmt(ml.precio);
    r.ml_beneficios = beneficiosML(ml);
    r.ml_link = ml.link;
    return r;
  }

  // Caso 4: sin stock en ningun lado
  return r;
}

const vertical = decidir(leerTN('Stock Vertical'), leerML('Precio ML Vertical'), base.link_vertical);
const redonda  = decidir(leerTN('Stock Redonda'),  leerML('Precio ML Redonda'),  base.link_redonda);

// Agrega los campos con prefijo vertical_ y redonda_
const salida = { ...base };
for (const [clave, valor] of Object.entries(vertical)) salida['vertical_' + clave] = valor;
for (const [clave, valor] of Object.entries(redonda))  salida['redonda_' + clave]  = valor;

return [{ json: salida }];

